'use strict'

// `pg/lib/type-overrides.js`, reduced to the shape that crashed the
// compiler. Three things have to be true at once and the middle one is the
// unobvious one:
//
//   1. an ES5 CONSTRUCTOR FUNCTION with an UNTYPED parameter, so it is an
//      implicit-any generic function rather than a class;
//   2. the same module writes `Overrides.prototype.<name> = function ...`,
//      whose receiver `Overrides.prototype` reads `Overrides` as a VALUE —
//      that is what compiles the body as the all-dyn default instance, a
//      monomorphized plain function whose frame takes no captures and owns
//      no `this` of its own;
//   3. inside that body, `this.<name> = <value>` in STATEMENT position,
//      whose receiver the dyn-receiver probe lowers speculatively.
//
// The probe reached `resolveThis`, the walk found the ENCLOSING class
// constructor's `this`, the capture fence fired, and computing its blame
// node called `declarationsOf(THIS_BINDING)` on a sentinel symbol with no
// declarations array: `TypeError: Cannot read properties of undefined
// (reading 'map')`, no code and no location.
function Overrides(userTypes) {
  this._types = userTypes || {}
  this.tag = 'over'
}

Overrides.prototype.get = function (name) {
  return this._types[name]
}

Overrides.prototype.set = function (name, value) {
  this._types[name] = value
  return this
}

// The enclosing frame the walk finds: a class whose constructor is what
// pulls the module in. Without it the stack has no `this` binding to
// reach and the walk answers null instead of fencing.
class Client {
  constructor(config) {
    this.name = 'client'
    this._over = new Overrides(config)
  }

  read(name) {
    return this._over.get(name)
  }
}

exports.Overrides = Overrides
exports.Client = Client
